private readonly MFAAvalonia.Services.AfkOptionControls _afkRows = new();
private bool _afkRendered;

private void PrepareRunOptions(Panel panel, DragItemViewModel source)
{
    _afkRows.Reset(); _afkRendered = false;
    panel.SetValue(Avalonia.Controls.Documents.TextElement.FontFamilyProperty, MFAAvalonia.Controls.PlayerUi.Font);
    panel.SetValue(Avalonia.Controls.Documents.TextElement.FontSizeProperty, MFAAvalonia.Controls.PlayerUi.BodySize);
    var afk = source.InterfaceItem?.Option?.FirstOrDefault(option => option.Name == "挂机模式");
    if (afk == null) return;
    var count = source.InterfaceItem?.Option?.FirstOrDefault(option => option.Name == "刷取次数");
    var oldUnlimited = source.InterfaceItem?.Repeatable == true && source.InterfaceItem.RepeatCount == -1
        || count?.Data?.TryGetValue("刷取次数", out var value) == true && value == "-1";
    if (oldUnlimited && !viewModel.Processor.IsTaskRunActive)
    {
        afk.Index = 1;
        if (source.InterfaceItem?.Repeatable == true && source.InterfaceItem.RepeatCount == -1) source.InterfaceItem.RepeatCount = 1;
        if (count?.Data != null)
        {
            count.Data["刷取次数"] = "1";
            if (MaaProcessor.Interface?.Option?.TryGetValue("刷取次数", out var definition) == true) UpdatePipeline(count, definition);
        }
        saveConfigurationAction();
    }
    var retry = source.InterfaceItem?.Option?.FirstOrDefault(option => option.Name == "失败自动重试");
    var retrySettings = retry?.SubOptions?.FirstOrDefault(option => option.Name == "失败重试设置");
    if (!viewModel.Processor.IsTaskRunActive && retrySettings?.Data?.TryGetValue("失败重试次数", out var oldRetries) == true && oldRetries == "0")
    {
        retry!.Index = 0;
        retrySettings.Data["失败重试次数"] = "3";
        if (MaaProcessor.Interface?.Option?.TryGetValue("失败重试设置", out var definition) == true) UpdatePipeline(retrySettings, definition);
        saveConfigurationAction();
    }
    AddOption(panel, afk, source);
}

private void AddRepeatOption(Panel panel, DragItemViewModel source)
{
    PrepareRunOptions(panel, source);
    if (source.InterfaceItem is not { Repeatable: true }) return;

    var grid = CreateBaseGrid();

    var textBlock = source.InterfaceItem.Option?.Any(option => option.Name == "挂机模式") == true
        ? new TextBlock { Text = "完成轮数", VerticalAlignment = VerticalAlignment.Center } : CreateLabelText("RepeatOption");
    Grid.SetColumn(textBlock, 0);
    grid.Children.Add(textBlock);

    var numericUpDown = new NumericUpDown
    {
        Value = source.InterfaceItem.RepeatCount ?? 1,
        VerticalAlignment = VerticalAlignment.Center,
        MinWidth = 120,
        Margin = new Thickness(0, 2, 0, 2),
        Increment = 1,
        Minimum = source.InterfaceItem.Option?.Any(option => option.Name == "挂机模式") == true ? 1 : -1,
        HorizontalAlignment = HorizontalAlignment.Stretch,
        Classes = { "TaskOptionLikeCombo" },
    };

    BindIdleEnabled(numericUpDown);

    numericUpDown.ValueChanged += (_, _) =>
    {
        source.InterfaceItem.RepeatCount = Convert.ToInt32(numericUpDown.Value);
        saveConfigurationAction();
    };

    Grid.SetColumn(numericUpDown, 1);
    AddResponsiveBehavior(grid, textBlock, numericUpDown);

    grid.Children.Add(numericUpDown);
    _afkRows.SetEnabled(source.InterfaceItem?.Option?.Any(o => o.Name == "挂机模式" && o.Index == 1) == true);
    if (source.InterfaceItem?.Option?.Any(o => o.Name == "挂机模式") == true) _afkRows.Add(grid);
    panel.Children.Add(grid);
}

private void AddOption(Panel panel, MaaInterface.MaaInterfaceSelectOption option, DragItemViewModel source)
{
    if (MaaProcessor.Interface?.Option?.TryGetValue(option.Name ?? string.Empty, out var interfaceOption) != true) return;

    // 过滤：根据 option.controller / option.resource 隐藏不适用项（任务 11）
